// Encryption at rest: the keys, the sealed form of a row, and the passphrase lock.
// docs/web-port/at-rest.md has the design and says plainly what it does and does not
// protect. Nothing here reads a browser global: WebCrypto, randomness, Argon2id and the
// clock come in through `VaultCrypto`.
//
// Two keys seal the database (`DataKeys`): an AES-256-GCM key for the rows and an
// HMAC-SHA-256 key that turns every text key (a peer id, a setting's name) into an opaque
// tag. Both are WebCrypto keys that cannot be exported. Without a passphrase they are
// generated by the browser and kept as `CryptoKey` objects in the `vault` store, so script
// never sees their bytes. With a passphrase they are 64 random bytes, kept only as a
// ciphertext under a key stretched from the passphrase with Argon2id.
import { fromHex, toHex, utf8 } from "./bytes.ts";
import type { StoreName } from "./platform.ts";
import {
  DATA_STORES,
  KEY_PATHS,
  PEER_INDEXED,
  PreconditionFailed,
  type RawStorage,
  type RawWriteOp,
  VAULT_STORE,
} from "./storage.ts";

/** The format of sealed rows and of the `vault` store's rows. */
export const VAULT_FORMAT = 1;
/** Sealed plaintext is padded to a multiple of this many bytes. */
export const PAD_BLOCK = 128;
/** The fewest characters a passphrase may have. */
export const MIN_PASSPHRASE = 8;

export interface KdfParams {
  alg: "argon2id";
  /** Argon2 version 0x13. */
  version: 19;
  memoryKiB: number;
  passes: number;
  lanes: number;
}

/**
 * Argon2id, 64 MiB, 3 passes, 1 lane: RFC 9106's second recommended setting with one lane,
 * because the wasm core runs on one thread. Stored with every use, so it can be raised.
 */
export const KDF_DEFAULT: KdfParams = Object.freeze({
  alg: "argon2id",
  version: 19,
  memoryKiB: 65536,
  passes: 3,
  lanes: 1,
});

/** The most a stored or imported `KdfParams` may ask for (the wasm core enforces it too). */
const KDF_MAX_MEMORY_KIB = 1 << 20;
const KDF_MAX_PASSES = 16;

export interface VaultCrypto {
  subtle: SubtleCrypto;
  /** Cryptographically strong bytes. */
  random(n: number): Uint8Array;
  /** Argon2id from the wasm core (`argon2id` of parolnet-wasm). Throws on bad parameters. */
  argon2id(
    passphrase: Uint8Array,
    salt: Uint8Array,
    memoryKiB: number,
    passes: number,
    lanes: number,
    len: number,
  ): Uint8Array;
  /** Milliseconds since the Unix epoch. */
  now(): number;
}

export type VaultErrorCode =
  /** The passphrase is not the one the keys were wrapped with (or the wrapped keys were changed). */
  | "WrongPassphrase"
  /** Too many wrong passphrases: `retryAtMs` says when the next try is allowed. */
  | "TooSoon"
  /** The vault is locked: unlock it first. */
  | "Locked"
  /** A row did not decrypt, or is not in a form this code knows. */
  | "Corrupt"
  /** The database was written by a newer version of the app. */
  | "Unsupported"
  /** A passphrase shorter than `MIN_PASSPHRASE`. */
  | "Weak"
  /** There is no passphrase to change or remove, or one is already set. */
  | "State";

/** Every error of this module. Its message never contains a passphrase, a key or a row. */
export class VaultError extends Error {
  constructor(readonly code: VaultErrorCode, message: string, readonly retryAtMs = 0) {
    super(message);
    this.name = "VaultError";
  }
}

export interface DataKeys {
  /** AES-256-GCM, not extractable: seals rows. */
  enc: CryptoKey;
  /** HMAC-SHA-256, not extractable: makes the tags that stand in for text keys. */
  mac: CryptoKey;
}

type Key = string | number;

/** A row as it is kept: the store's key (and index) column, and the sealed row. */
export interface SealedRow {
  v: typeof VAULT_FORMAT;
  /** The nonce: 12 random bytes, new for every write. */
  n: Uint8Array;
  /** AES-256-GCM ciphertext and tag of the padded JSON of the row. */
  c: Uint8Array;
  [column: string]: unknown;
}

/** store `vault`, key `"keys"`. */
export type KeysRow =
  | { id: "keys"; format: number; mode: "device"; enc: CryptoKey; mac: CryptoKey }
  | {
    id: "keys";
    format: number;
    mode: "passphrase";
    kdf: KdfParams;
    salt: Uint8Array;
    nonce: Uint8Array;
    /** AES-256-GCM of the 64 key bytes under the passphrase's key. */
    wrapped: Uint8Array;
  };

/** store `vault`, key `"attempts"`: wrong passphrases in a row, for the backoff. */
interface AttemptsRow {
  id: "attempts";
  failed: number;
  lastMs: number;
}

// The buffer types WebCrypto wants (`BufferSource` over an `ArrayBuffer`).
const buf = (bytes: Uint8Array): Uint8Array<ArrayBuffer> => bytes as Uint8Array<ArrayBuffer>;

// ── JSON with bytes ──────────────────────────────────────────────

const BYTES = "$bytes";

function toBase64(bytes: Uint8Array): string {
  let text = "";
  for (let i = 0; i < bytes.length; i += 0x8000) {
    text += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  }
  return btoa(text);
}

function fromBase64(text: string): Uint8Array {
  const raw = atob(text);
  const out = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) out[i] = raw.charCodeAt(i);
  return out;
}

/**
 * A row as text: JSON, with a `Uint8Array` written as `{"$bytes": base64}`. Anything else
 * JSON cannot hold (a Map, a Blob, an ArrayBuffer) throws, so nothing is stored mangled.
 */
export function encodeRow(row: unknown): string {
  return JSON.stringify(row, (_key, value) => {
    if (value instanceof Uint8Array) return { [BYTES]: toBase64(value) };
    if (
      value instanceof ArrayBuffer || value instanceof Map || value instanceof Set ||
      (typeof Blob !== "undefined" && value instanceof Blob)
    ) {
      throw new VaultError("Corrupt", "a row holds a value that cannot be stored");
    }
    return value;
  });
}

export function decodeRow(text: string): unknown {
  return JSON.parse(text, (_key, value) => {
    if (
      value !== null && typeof value === "object" && typeof value[BYTES] === "string" &&
      Object.keys(value).length === 1
    ) {
      return fromBase64(value[BYTES]);
    }
    return value;
  });
}

/** UTF-8 of `text`, padded with spaces (which JSON ignores) to a multiple of `PAD_BLOCK`. */
function padded(text: string): Uint8Array {
  const bytes = utf8(text);
  const out = new Uint8Array(Math.ceil((bytes.length + 1) / PAD_BLOCK) * PAD_BLOCK).fill(0x20);
  out.set(bytes);
  return out;
}

// ── Keys ─────────────────────────────────────────────────────────

const AES = { name: "AES-GCM", length: 256 } as const;
const HMAC = { name: "HMAC", hash: "SHA-256", length: 256 } as const;

/** Two fresh keys made by the browser. Their bytes never exist in script. */
export async function generateDeviceKeys(crypto: VaultCrypto): Promise<DataKeys> {
  return {
    enc: await crypto.subtle.generateKey(AES, false, ["encrypt", "decrypt"]) as CryptoKey,
    mac: await crypto.subtle.generateKey(HMAC, false, ["sign"]) as CryptoKey,
  };
}

async function importKeys(crypto: VaultCrypto, raw: Uint8Array): Promise<DataKeys> {
  return {
    enc: await crypto.subtle.importKey("raw", buf(raw.subarray(0, 32)), AES, false, [
      "encrypt",
      "decrypt",
    ]),
    mac: await crypto.subtle.importKey("raw", buf(raw.subarray(32, 64)), HMAC, false, ["sign"]),
  };
}

/** What a person typed, as the bytes that are stretched: Unicode NFKC, UTF-8. */
export function passphraseBytes(passphrase: string): Uint8Array {
  return utf8(passphrase.normalize("NFKC"));
}

export function checkKdf(kdf: KdfParams): void {
  if (
    !kdf || kdf.alg !== "argon2id" || kdf.version !== 19 ||
    !Number.isInteger(kdf.memoryKiB) || !Number.isInteger(kdf.passes) ||
    !Number.isInteger(kdf.lanes) || kdf.memoryKiB < 8 || kdf.memoryKiB > KDF_MAX_MEMORY_KIB ||
    kdf.passes < 1 || kdf.passes > KDF_MAX_PASSES || kdf.lanes < 1 || kdf.lanes > 16
  ) {
    throw new VaultError("Unsupported", "the key derivation settings are not ones this app uses");
  }
}

/**
 * The AES-256-GCM key of a passphrase: Argon2id over its NFKC UTF-8 bytes and `salt`.
 * The stretched bytes are wiped once the browser holds the key.
 */
export async function passphraseKey(
  crypto: VaultCrypto,
  passphrase: string,
  salt: Uint8Array,
  kdf: KdfParams,
): Promise<CryptoKey> {
  checkKdf(kdf);
  const typed = passphraseBytes(passphrase);
  let stretched: Uint8Array | null = null;
  try {
    stretched = crypto.argon2id(typed, salt, kdf.memoryKiB, kdf.passes, kdf.lanes, 32);
    return await crypto.subtle.importKey("raw", buf(stretched), AES, false, [
      "encrypt",
      "decrypt",
    ]);
  } finally {
    typed.fill(0);
    stretched?.fill(0);
  }
}

/** What the wrapped keys are bound to: the format and every parameter that made their key. */
function lockAad(kdf: KdfParams, salt: Uint8Array): Uint8Array {
  return utf8(JSON.stringify([
    "parolnet-web-lock",
    VAULT_FORMAT,
    kdf.alg,
    kdf.version,
    kdf.memoryKiB,
    kdf.passes,
    kdf.lanes,
    toHex(salt),
  ]));
}

/** New data keys, and the row that keeps them under `passphrase`. */
export async function newPassphraseKeys(
  crypto: VaultCrypto,
  passphrase: string,
  kdf: KdfParams = KDF_DEFAULT,
): Promise<{ keys: DataKeys; row: KeysRow }> {
  const raw = crypto.random(64);
  try {
    const salt = crypto.random(16);
    const nonce = crypto.random(12);
    const kek = await passphraseKey(crypto, passphrase, salt, kdf);
    const wrapped = new Uint8Array(
      await crypto.subtle.encrypt(
        { name: "AES-GCM", iv: buf(nonce), additionalData: buf(lockAad(kdf, salt)) },
        kek,
        buf(raw),
      ),
    );
    return {
      keys: await importKeys(crypto, raw),
      row: {
        id: "keys",
        format: VAULT_FORMAT,
        mode: "passphrase",
        kdf: { ...kdf },
        salt,
        nonce,
        wrapped,
      },
    };
  } finally {
    raw.fill(0);
  }
}

/** The data keys of a passphrase row. Rejects with `WrongPassphrase`. */
export async function unwrapKeys(
  crypto: VaultCrypto,
  row: Extract<KeysRow, { mode: "passphrase" }>,
  passphrase: string,
): Promise<DataKeys> {
  const kek = await passphraseKey(crypto, passphrase, row.salt, row.kdf);
  let raw: Uint8Array;
  try {
    raw = new Uint8Array(
      await crypto.subtle.decrypt(
        { name: "AES-GCM", iv: buf(row.nonce), additionalData: buf(lockAad(row.kdf, row.salt)) },
        kek,
        buf(row.wrapped),
      ),
    );
  } catch {
    throw new VaultError("WrongPassphrase", "that is not the passphrase");
  }
  try {
    if (raw.length !== 64) throw new VaultError("Corrupt", "the stored keys are unreadable");
    return await importKeys(crypto, raw);
  } finally {
    raw.fill(0);
  }
}

// ── Sealing rows ─────────────────────────────────────────────────

/**
 * What stands in for a text key: the first 16 bytes of HMAC-SHA-256 over the store's name
 * and the key, hex. The same key gives a different tag in each store.
 */
export async function tagOf(
  crypto: VaultCrypto,
  keys: DataKeys,
  store: string,
  key: string,
): Promise<string> {
  const mac = await crypto.subtle.sign("HMAC", keys.mac, buf(utf8(`${store}\u0000${key}`)));
  return toHex(new Uint8Array(mac).subarray(0, 16));
}

/** What a sealed row is bound to: the format, its store and the key it is kept under. */
function rowAad(store: string, storedKey: Key): Uint8Array {
  return utf8(JSON.stringify(["parolnet-web-row", VAULT_FORMAT, store, storedKey]));
}

/** Seals rows with one set of keys, and remembers the tags it has computed. */
export class Sealer {
  private readonly tags = new Map<string, string>();

  constructor(private readonly crypto: VaultCrypto, readonly keys: DataKeys) {}

  /** The key a row is kept under: a number as it is, a text key as its tag. */
  async storedKey(store: string, key: Key): Promise<Key> {
    if (typeof key === "number") return key;
    const id = `${store}\u0000${key}`;
    let tag = this.tags.get(id);
    if (tag === undefined) {
      tag = await tagOf(this.crypto, this.keys, store, key);
      if (this.tags.size > 4096) this.tags.clear();
      this.tags.set(id, tag);
    }
    return tag;
  }

  async seal(store: StoreName, row: unknown): Promise<SealedRow> {
    const column = KEY_PATHS[store];
    const fields = row as Record<string, unknown>;
    const key = fields?.[column];
    if (typeof key !== "string" && typeof key !== "number") {
      throw new VaultError("Corrupt", `a ${store} row has no key`);
    }
    const storedKey = await this.storedKey(store, key);
    const nonce = this.crypto.random(12);
    const plain = padded(encodeRow(row));
    let sealed: ArrayBuffer;
    try {
      sealed = await this.crypto.subtle.encrypt(
        { name: "AES-GCM", iv: buf(nonce), additionalData: buf(rowAad(store, storedKey)) },
        this.keys.enc,
        buf(plain),
      );
    } finally {
      plain.fill(0);
    }
    const out: SealedRow = { v: VAULT_FORMAT, n: nonce, c: new Uint8Array(sealed) };
    out[column] = storedKey;
    if (PEER_INDEXED.includes(store) && column !== "peerId") {
      const peer = fields.peerId;
      if (typeof peer !== "string") {
        throw new VaultError("Corrupt", `a ${store} row has no contact`);
      }
      out.peerId = await this.storedKey(store, peer);
    }
    return out;
  }

  /** The row a sealed row holds. Rejects with `Corrupt` when it was changed or moved. */
  async open<T>(store: StoreName, sealed: unknown): Promise<T> {
    const row = sealed as SealedRow | undefined;
    const storedKey = row?.[KEY_PATHS[store]];
    if (
      !row || row.v !== VAULT_FORMAT || !(row.n instanceof Uint8Array) ||
      !(row.c instanceof Uint8Array) ||
      (typeof storedKey !== "string" && typeof storedKey !== "number")
    ) {
      throw new VaultError("Corrupt", `a ${store} row is not sealed`);
    }
    let plain: Uint8Array;
    try {
      plain = new Uint8Array(
        await this.crypto.subtle.decrypt(
          { name: "AES-GCM", iv: buf(row.n), additionalData: buf(rowAad(store, storedKey)) },
          this.keys.enc,
          buf(row.c),
        ),
      );
    } catch {
      throw new VaultError("Corrupt", `a ${store} row does not decrypt`);
    }
    try {
      return decodeRow(new TextDecoder("utf-8", { fatal: true }).decode(plain)) as T;
    } catch {
      throw new VaultError("Corrupt", `a ${store} row is unreadable`);
    } finally {
      plain.fill(0);
    }
  }
}

/** True for a row in the sealed form (as opposed to a plaintext row of version 1). */
export function isSealed(row: unknown): boolean {
  const r = row as SealedRow | undefined;
  return !!r && r.v === VAULT_FORMAT && r.n instanceof Uint8Array && r.c instanceof Uint8Array;
}

/**
 * The operations that replace every row of `rows` (as kept now, under `oldKeyOf`) by the
 * sealed form of `plain` under `sealer`. Each sealed row is opened again and compared with
 * what went in before it is accepted.
 */
async function resealOps(
  sealer: Sealer,
  plain: Map<StoreName, unknown[]>,
  oldKeys: Map<StoreName, Key[]>,
): Promise<RawWriteOp[]> {
  const ops: RawWriteOp[] = [];
  for (const store of DATA_STORES) {
    const column = KEY_PATHS[store];
    const kept = new Set<Key>();
    for (const row of plain.get(store) ?? []) {
      const sealed = await sealer.seal(store, row);
      if (encodeRow(await sealer.open(store, sealed)) !== encodeRow(row)) {
        throw new VaultError("Corrupt", `a ${store} row did not survive sealing`);
      }
      kept.add(sealed[column] as Key);
      ops.push({ op: "put", store, value: sealed });
    }
    // What was there under a key that is not written again (a clear text key, an old tag).
    for (const key of oldKeys.get(store) ?? []) {
      if (!kept.has(key)) ops.unshift({ op: "delete", store, key });
    }
  }
  return ops;
}

function keysOf(rows: Map<string, unknown[]>): Map<StoreName, Key[]> {
  const out = new Map<StoreName, Key[]>();
  for (const store of DATA_STORES) {
    out.set(
      store,
      (rows.get(store) ?? []).map((row) => (row as Record<string, Key>)[KEY_PATHS[store]]),
    );
  }
  return out;
}

// ── Backoff ──────────────────────────────────────────────────────

/** How long after the `failed`-th wrong passphrase in a row the next try must wait. */
export function backoffMs(failed: number): number {
  if (failed < 3) return 0;
  return Math.min(5000 * 2 ** (failed - 3), 300_000);
}

// ── The vault ────────────────────────────────────────────────────

/**
 * The keys of one database. `Vault.open` seals a database that is not sealed yet (a new
 * one, or version 1's plaintext rows) and reports whether a passphrase is needed.
 */
export class Vault {
  private sealerNow: Sealer | null = null;

  private constructor(
    readonly raw: RawStorage,
    private readonly crypto: VaultCrypto,
    private row: KeysRow,
    /** Rows that were plaintext and were sealed when this vault was opened. */
    readonly migrated: number,
  ) {}

  static async open(raw: RawStorage, crypto: VaultCrypto): Promise<Vault> {
    let migrated = 0;
    let row = await raw.get<KeysRow>(VAULT_STORE, "keys");
    let keys: DataKeys | null = null;
    if (!row) {
      try {
        const made = await sealFirst(raw, crypto);
        row = made.row;
        keys = made.keys;
        migrated = made.migrated;
      } catch (error) {
        if (!(error instanceof PreconditionFailed)) throw error;
        // Another tab sealed the database in the meantime: use what it made.
        row = await raw.get<KeysRow>(VAULT_STORE, "keys");
        if (!row) throw new VaultError("Corrupt", "the storage keys are missing");
      }
    }
    if (row.format !== VAULT_FORMAT || (row.mode !== "device" && row.mode !== "passphrase")) {
      throw new VaultError("Unsupported", "this database was written by a newer ParolNet");
    }
    const vault = new Vault(raw, crypto, row, migrated);
    if (row.mode === "device") {
      vault.sealerNow = new Sealer(crypto, keys ?? { enc: row.enc, mac: row.mac });
    }
    return vault;
  }

  /** A passphrase is needed before anything can be read. */
  get locked(): boolean {
    return this.sealerNow === null;
  }

  get hasPassphrase(): boolean {
    return this.row.mode === "passphrase";
  }

  /** The current keys. Throws `Locked`. */
  get sealer(): Sealer {
    if (!this.sealerNow) throw new VaultError("Locked", "ParolNet is locked");
    return this.sealerNow;
  }

  /** When the next passphrase may be tried (0: now). */
  async retryAtMs(): Promise<number> {
    const attempts = await this.raw.get<AttemptsRow>(VAULT_STORE, "attempts");
    if (!attempts) return 0;
    const now = this.crypto.now();
    // A clock that went backwards does not shorten the wait.
    const last = Math.min(attempts.lastMs, now);
    const at = last + backoffMs(attempts.failed);
    return at > now ? at : 0;
  }

  /**
   * Check `passphrase` against the stored row. Counts a wrong one (before the slow part, so
   * closing the tab does not skip the count) and enforces the wait.
   */
  private async verify(passphrase: string): Promise<DataKeys> {
    const row = this.row;
    if (row.mode !== "passphrase") throw new VaultError("State", "no passphrase is set");
    const retryAt = await this.retryAtMs();
    if (retryAt > 0) throw new VaultError("TooSoon", "too many wrong passphrases", retryAt);
    const before = await this.raw.get<AttemptsRow>(VAULT_STORE, "attempts");
    const counted: AttemptsRow = {
      id: "attempts",
      failed: (before?.failed ?? 0) + 1,
      lastMs: this.crypto.now(),
    };
    await this.raw.write([{ op: "put", store: VAULT_STORE, value: counted }]);
    const keys = await unwrapKeys(this.crypto, row, passphrase);
    await this.raw.write([{ op: "delete", store: VAULT_STORE, key: "attempts" }]);
    return keys;
  }

  /** Unlock with the passphrase. Rejects with `WrongPassphrase` or `TooSoon`. */
  async unlock(passphrase: string): Promise<void> {
    if (!this.locked) return;
    this.sealerNow = new Sealer(this.crypto, await this.verify(passphrase));
  }

  /**
   * Seal every row again under `next` and replace the keys row, in one transaction. Runs
   * inside `exclusive`, so no other read or write of the database runs meanwhile.
   */
  private async rekey(next: { keys: DataKeys; row: KeysRow }): Promise<void> {
    const old = this.sealer;
    const kept = await this.raw.dump(DATA_STORES);
    const plain = new Map<StoreName, unknown[]>();
    for (const store of DATA_STORES) {
      const rows: unknown[] = [];
      for (const sealed of kept.get(store) ?? []) rows.push(await old.open(store, sealed));
      plain.set(store, rows);
    }
    const sealer = new Sealer(this.crypto, next.keys);
    const ops = await resealOps(sealer, plain, keysOf(kept));
    ops.push({ op: "put", store: VAULT_STORE, value: next.row });
    ops.push({ op: "delete", store: VAULT_STORE, key: "attempts" });
    await this.raw.write(ops);
    this.row = next.row;
    this.sealerNow = sealer;
  }

  /** `SealedStorage` puts its queue here, so a change of keys waits its turn among the writes. */
  exclusive: <T>(fn: () => Promise<T>) => Promise<T> = (fn) => fn();

  /** Lock with a passphrase: new keys, kept only under it. */
  setPassphrase(passphrase: string, kdf: KdfParams = KDF_DEFAULT): Promise<void> {
    return this.exclusive(async () => {
      if (this.hasPassphrase) throw new VaultError("State", "a passphrase is already set");
      this.sealer;
      checkPassphrase(passphrase);
      await this.rekey(await newPassphraseKeys(this.crypto, passphrase, kdf));
    });
  }

  /** Rejects with `WrongPassphrase` or `TooSoon` when `current` is not the passphrase. */
  changePassphrase(current: string, next: string, kdf: KdfParams = KDF_DEFAULT): Promise<void> {
    return this.exclusive(async () => {
      this.sealer;
      checkPassphrase(next);
      await this.verify(current);
      await this.rekey(await newPassphraseKeys(this.crypto, next, kdf));
    });
  }

  /** Back to keys the browser keeps. Rejects like `changePassphrase`. */
  removePassphrase(current: string): Promise<void> {
    return this.exclusive(async () => {
      this.sealer;
      await this.verify(current);
      const keys = await generateDeviceKeys(this.crypto);
      await this.rekey({
        keys,
        row: { id: "keys", format: VAULT_FORMAT, mode: "device", enc: keys.enc, mac: keys.mac },
      });
    });
  }

  /** Delete the database, keys and all (a forgotten passphrase). */
  destroy(): Promise<void> {
    this.sealerNow = null;
    return this.raw.destroy();
  }
}

function checkPassphrase(passphrase: string): void {
  if ([...passphrase.normalize("NFKC")].length < MIN_PASSPHRASE) {
    throw new VaultError("Weak", `a passphrase needs at least ${MIN_PASSPHRASE} characters`);
  }
}

/**
 * A database with no keys yet: make them and seal whatever rows there are (version 1 kept
 * them in plaintext), all in one transaction that also refuses to run twice.
 */
async function sealFirst(
  raw: RawStorage,
  crypto: VaultCrypto,
): Promise<{ keys: DataKeys; row: KeysRow; migrated: number }> {
  const kept = await raw.dump(DATA_STORES);
  const plain = new Map<StoreName, unknown[]>();
  let migrated = 0;
  for (const store of DATA_STORES) {
    const rows = kept.get(store) ?? [];
    if (rows.some(isSealed)) {
      // Sealed rows without their keys: nothing can read them, and nothing may overwrite them.
      throw new VaultError("Corrupt", "the storage keys are missing");
    }
    plain.set(store, rows);
    migrated += rows.length;
  }
  const keys = await generateDeviceKeys(crypto);
  const row: KeysRow = {
    id: "keys",
    format: VAULT_FORMAT,
    mode: "device",
    enc: keys.enc,
    mac: keys.mac,
  };
  const ops = await resealOps(new Sealer(crypto, keys), plain, keysOf(kept));
  ops.push({ op: "put", store: VAULT_STORE, value: row });
  await raw.write(ops, { unlessExists: { store: VAULT_STORE, key: "keys" } });
  // What is there now is what was written: as many rows, every one sealed.
  const after = await raw.dump(DATA_STORES);
  for (const store of DATA_STORES) {
    const rows = after.get(store) ?? [];
    if (rows.length !== (plain.get(store) ?? []).length || !rows.every(isSealed)) {
      throw new VaultError("Corrupt", `sealing the ${store} rows did not complete`);
    }
  }
  return { keys, row, migrated };
}

/** Decode hex that must be hex (a stored salt or nonce of a backup header). */
export function hexBytes(text: unknown, length: number): Uint8Array {
  const bytes = typeof text === "string" ? fromHex(text) : null;
  if (!bytes || bytes.length !== length) {
    throw new VaultError("Corrupt", "a header field is unreadable");
  }
  return bytes;
}
